/*
    h4_Input_Check_Value フォームで設定した値の取得
    OKボタンで動作
    
    参考：h4_frm_getSettingEvents
            同じ形式なので全く同じメソッド 仕様変更に備えメソッド自体は分けておく
*/

    const iomInv = aras.IomInnovator;

    // フォーム上のチェックボックスを取得
    var elements = document.querySelectorAll('input');
    
    var strEvents = [];
    for (var i = 0; i < elements.length; i++) {

        var ele = elements[i];
        var eleName = ele.name;
        
        if (ele.type != "checkbox") {
            continue;       // チェックボックス以外は処理対象外
        }
        
        // チェックしてあるチェックボックスを取得
        if (! ele.checked) {
            continue;
        }
        
        strEvents.push(ele.id);
    }

    // ダイアログクローズ処理（カンマ[,]区切り文字列生成、0: チェックしたイベント
    parent.dialogArguments.dialog.close(strEvents);

return;

/*
    開発拠点設定画面の初期化
    参考：h4_setEventInit
*/
    const iomInv = aras.IomInnovator;

    var listName = parent.frameElement.dialogArguments.targetListName;

    // リストを取得
    var listItem = iomInv.newItem("List", "get");
    listItem.setAttribute("select", "id");
    listItem.setProperty("name", listName);
    listItem = listItem.apply();
    if(listItem.isError())
    {
        msg = getUserMessage("h4_C_E_0002");
        aras.AlertError(msg);
        return;
    }
    
    var listValue = iomInv.newItem("Value", "get");
    listValue.setAttribute("select", "label,value");
    listValue.setProperty("source_id", listItem.getID());
    listValue = listValue.apply();
    if(listValue.isError())
    {
        msg = getUserMessage("h4_C_E_0002");
        aras.AlertError(msg);
        return;
    }

    var targetListLabel = [];
    for (var i = 0; i < listValue.getItemCount(); i++)
    {
        var wkItem = listValue.getItemByIndex(i);
        var strLabel = wkItem.getProperty("label");
        targetListLabel.push(strLabel);
    }    

    //チェックボックス作成
    addCheckBoxField(targetListLabel);

/*
    チェックボックス作成メソッド
*/
function addCheckBoxField(values) {

    for (var j = 0; j < Math.ceil(values.length / 8); j++) {
        var mainDiv = document.getElementById('checkBoxField');
        var subDiv = document.createElement('div');
        
        for (var i =0; i < 8; i++) {
            
            var count = i + (j * 8);
            if (count >= values.length) {
                break;
            }
            
            // チェックボックス作成
            var wkVal = values[count];
            var newField = document.createElement('input');
            newField.type = 'checkbox';
            newField.id = wkVal;
            
            // チェックボックスのラベルを作成
            var newLabel = document.createElement('label');
            newLabel.htmlFor = newField.id;
            newLabel.textContent = wkVal + "　　";
            newLabel.style.fontWeight = 'bold';

            subDiv.appendChild(newField);
            subDiv.appendChild(newLabel);
        }
        
        mainDiv.appendChild(subDiv);
        mainDiv.appendChild(document.createElement('br'));

    }
}   

// メッセージを取得
function getUserMessage(messageName){
            var userMsgItem =  aras.IomInnovator.newItem("UserMessage","get");
            userMsgItem.setAttribute("select","text");
            userMsgItem.setProperty("name",messageName);
            userMsgItem = userMsgItem.apply();
            return  userMsgItem.getProperty("text","");
};

return;
